-- Phase 4D.9M production fingerprint (READ-ONLY). Generated in 4D.9L from the migration-0018 schema.
-- Run with psql against production (owner or vo_app) immediately BEFORE and AFTER migrating 0019/0020, with the
-- application quiet, and diff the two outputs. Every row must be identical; only the migration count changes
-- (19 -> 21). Hashes cover each table's 0018 columns only, so the additive 0020 columns do not affect them.
-- audit_event and app_session change with ordinary use, so only their counts are listed.
\pset tuples_only on
\pset format unaligned
begin transaction read only;
select 'migrations', count(*)::text from drizzle.__drizzle_migrations;
select 'migration ' || id, hash from drizzle.__drizzle_migrations order by id;
select 'app_credential', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,user_id,password_hash,password_set_at,disabled_at,created_at)::text r from app_credential) x;
select 'app_session', count(*)::text from app_session;
select 'app_user', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,email,display_name,created_at)::text r from app_user) x;
select 'assumption', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_driver_version_id,project_id,statement,evidence_status,notes,sort_order,created_at)::text r from assumption) x;
select 'assurance_review', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,value_case_id,sequence,trigger,trigger_evidence_id,against_version_id,previous_review_id,review_date,status,what_changed,why_it_matters,summary,created_by,created_at,finalised_by,finalised_at,unattributed_realised_value,unattributed_realised_rationale,matter_snapshot_at)::text r from assurance_review) x;
select 'audit_event', count(*)::text from audit_event;
select 'client', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,name,created_at)::text r from client) x;
select 'decision', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,assurance_review_id,project_id,selected_scenario_id,decided_by_person_id,decided_on,rationale,economic_consequence,supporting_evidence_id,recorded_by,recorded_at)::text r from decision) x;
select 'document', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,title,source_description,source_person_id,uri,storage_key,original_filename,mime_type,size_bytes,sha256,received_on,recorded_by,created_at)::text r from document) x;
select 'evidence', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,code,title,summary,document_id,source_person_id,evidence_date,received_on,supersedes_evidence_id,is_material_change,material_change_note,recorded_by,created_at)::text r from evidence) x;
select 'evidence_link', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,evidence_id,project_id,value_driver_version_id,assumption_id,relevance_note,created_at,assurance_review_id,value_leakage_id,value_driver_id)::text r from evidence_link) x;
select 'information_request', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,reference,title,status,issued_on,closed_on,created_at,purpose)::text r from information_request) x;
select 'information_request_item', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,information_request_id,project_id,sequence,description,requested_from_person_id,due_on,value_driver_id,status,fulfilled_by_evidence_id,notes,created_at,value_leakage_id)::text r from information_request_item) x;
select 'key_date', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,kind,label,date,notes,created_at)::text r from key_date) x;
select 'leakage_assessment', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_leakage_id,assurance_review_id,project_id,total_amount,unrecoverable_amount,unrecoverable_rationale,unrecoverable_validated_by,assessment_note,assessed_at,created_at,snapshot_taken_at,snapshot_status,snapshot_stage,snapshot_title,snapshot_description,snapshot_owner_person_id,snapshot_driver_ids,snapshot_consultant_assessment,snapshot_required_decision_date,snapshot_remediation_plan,snapshot_monitor_until)::text r from leakage_assessment) x;
select 'person', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,client_id,name,title,organisation,email,created_at)::text r from person) x;
select 'project', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,client_id,code,name,context,status,currency,value_basis_description,value_period_start,value_period_end,created_at)::text r from project) x;
select 'project_stakeholder', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,person_id,client_id,role_description,notes,created_at)::text r from project_stakeholder) x;
select 'recommendation', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,assurance_review_id,project_id,scenario_id,narrative,issued_by,issued_at,created_by,created_at)::text r from recommendation) x;
select 'report_document', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,key,sha256,content,bytes,created_by,created_at)::text r from report_document) x;
select 'report_issue', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,type,information_request_id,value_case_version_id,assurance_review_id,value_change_id,subject_status,issue_number,title,snapshot,snapshot_sha256,renderer_version,document_key,document_sha256,document_bytes,issued_by,issued_by_name,issued_at)::text r from report_issue) x;
select 'scenario', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,assurance_review_id,project_id,label,kind,total_value,narrative,sort_order,created_at)::text r from scenario) x;
select 'value_case', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,vco_person_id,created_at)::text r from value_case) x;
select 'value_case_version', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_case_id,project_id,version_number,kind,status,based_on_version_id,title,summary,stated_total_value,created_by,created_at,recorded_at,proposed_at,proposed_by,authorised_on,authorised_by_person_id,authorisation_evidence_id,authorisation_note,authorisation_recorded_by,authorisation_recorded_at,superseded_at)::text r from value_case_version) x;
select 'value_change', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,value_case_id,code,from_version_id,to_version_id,assurance_review_id,decision_id,reason,economic_impact_narrative,stated_change_amount,status,created_by,created_at,proposed_at,proposed_by,authorised_on,authorised_by_person_id,authorisation_evidence_id,authorisation_note,authorisation_recorded_by,authorisation_recorded_at,closed_at,closed_by,closure_note)::text r from value_change) x;
select 'value_driver', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_case_id,project_id,code,created_at)::text r from value_driver) x;
select 'value_driver_record', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_driver_id,project_id,name,description,metric,metric_unit,baseline_value,target_value,calculation_rationale,working_estimate,estimate_recorded_by,estimate_recorded_at,avo_person_id,qualification_status,evidence_status,notes,identified_on,origin_value_leakage_id,initialised_from_version_id,created_by,created_at)::text r from value_driver_record) x;
select 'value_driver_record_assumption', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_driver_record_id,project_id,statement,evidence_status,notes,sort_order,created_at)::text r from value_driver_record_assumption) x;
select 'value_driver_version', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_case_version_id,value_driver_id,value_case_id,project_id,name,description,metric,metric_unit,baseline_value,target_value,calculation_rationale,financial_value,timing_description,benefit_start_date,benefit_full_date,avo_person_id,qualification_status,evidence_status,notes,sort_order,created_at)::text r from value_driver_version) x;
select 'value_leakage', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,project_id,value_case_id,code,title,description,identified_in_review_id,response_owner_person_id,status,required_decision_date,consultant_assessment,created_by,created_at,identified_on,stage,working_total_amount,working_unrecoverable_amount,working_unrecoverable_rationale,working_assessed_by,working_assessed_at,remediation_plan,monitor_until,closure_note)::text r from value_leakage) x;
select 'value_leakage_driver', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,value_leakage_id,value_case_id,value_driver_id,project_id,created_at)::text r from value_leakage_driver) x;
select 'value_position', count(*) || ' ' || coalesce(md5(string_agg(r, '|' order by r)), 'empty') from (select json_build_array(id,assurance_review_id,project_id,value_case_id,value_driver_id,current_forecast,realised_value,forecast_rationale,realised_value_rationale,created_at,forecast_not_assessed)::text r from value_position) x;
rollback;
